import fcp.*;
import dev.fcp.dual.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static fcp.Schema.*;

/** Runs the actual Java rules, actual Python child process, and durable test repository.
 * Results intentionally do not assert Spring/RuoYi/MySQL/browser integration.
 */
public final class DualFlowRegression {
    static Path root;
    static final List<Object> tests=new ArrayList<>();
    interface Test{void run()throws Exception;}
    static void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
    static void run(String name,Test t){long time=System.nanoTime();try{t.run();tests.add(Json.obj("name",name,"status","PASS","ms",(System.nanoTime()-time)/1000000));}catch(Throwable e){tests.add(Json.obj("name",name,"status","FAIL","error",e.toString()));e.printStackTrace(System.err);}}
    static void reject(String code,Runnable r){try{r.run();throw new AssertionError("Expected "+code);}catch(FcpException e){check(code.equals(e.code),"expected "+code+" got "+e.code+": "+e.getMessage());}}
    static String key(){return UUID.randomUUID().toString();}
    static Map<String,Object> who(String subject,boolean all,String... permissions){return Json.obj("subject",subject,"viewAll",all,"permissions",List.of(permissions));}
    static final Map<String,Object> STAFF=who("101",false,"purchase.create","purchase.list","purchase.get","purchase.history","purchase.submit","repair.create","repair.list","repair.get","repair.history","repair.close");
    static final Map<String,Object> OTHER=who("102",false,"purchase.create","purchase.list","purchase.get","purchase.history","purchase.submit","repair.create","repair.list","repair.get","repair.history","repair.close");
    static final Map<String,Object> MANAGER=who("201",true,"*");
    static final Map<String,Object> TECH=who("301",false,"repair.list","repair.get","repair.history","repair.resolve");
    static final class Fixture implements AutoCloseable{
        final RecordStore store;final Engine engine;final AtomicBoolean permitted=new AtomicBoolean(true);long generation=1;String instance;
        Fixture()throws Exception{this(root,Files.createTempDirectory("fcp-data-").resolve("records.json"));}
        Fixture(Path runtime,Path data)throws Exception{store=new FileRecordStore(data);engine=DualSystem.create(runtime,store,(c,target,op)->{if(!permitted.get())throw new FcpException("FORBIDDEN","revoked");if(target.contains(".workflow/")){String permission=target.split("\\.")[0]+"."+op;List<Object> values=arr(c.attributes,"permissions");if(!values.contains("*")&&!values.contains(permission))throw new FcpException("FORBIDDEN",permission);}});instance=str(engine.publish("tenant-a","ruoyi.dual",0).get("instance"));engine.publish("tenant-b","ruoyi.dual",0);}
        Map<String,Object> call(String kind,String op,Map<String,Object> data,Map<String,Object> actor){return map(engine.invoke("tenant-a",kind,op,data,actor,generation,instance));}
        Map<String,Object> create(String kind,Map<String,Object> data,Map<String,Object> actor){return call(kind,"create",Json.obj("data",data,"requestKey",key()),actor);}
        Map<String,Object> act(String kind,String op,Map<String,Object> record,Map<String,Object> data,Map<String,Object> actor){return call(kind,op,Json.obj("id",record.get("id"),"expectedVersion",record.get("version"),"data",data,"requestKey",key()),actor);}
        public void close(){engine.close();store.close();}
    }
    static Map<String,Object> purchase(){return Json.obj("title","实验室设备采购","amount","12000.00");}
    static Map<String,Object> repair(){return Json.obj("title","机房电脑无法启动","description","3号机房12号设备","severity","urgent");}
    static void state(Map<String,Object> row,String state,long version){check(obj(row,"body").get("status").equals(state),"state "+state);check(number(row.get("version"))==version,"version "+version);}
    static Path copyRuntime()throws Exception{Path copy=Files.createTempDirectory("fcp-runtime-");try(var files=Files.walk(root)){for(Path p:files.toList()){Path dest=copy.resolve(root.relativize(p));if(Files.isDirectory(p))Files.createDirectories(dest);else Files.copy(p,dest);}}return copy;}
    public static void main(String[] args)throws Exception{
        root=Path.of(args[0]);
        run("java_purchase_create_submit_approve",()->{try(Fixture f=new Fixture()){Map<String,Object> row=f.create("purchase",purchase(),STAFF);state(row,"draft",1);row=f.act("purchase","submit",row,Map.of(),STAFF);state(row,"submitted",2);row=f.act("purchase","approve",row,Json.obj("comment","预算已复核"),MANAGER);state(row,"approved",3);List<Object> events=arr(f.call("purchase","history",Json.obj("id",row.get("id")),STAFF),"items");check(events.size()==3,"3 committed audit records");for(Object e:events)check(map(e).get("engine").equals("java-native"),"native JVM implementation");}});
        run("python_repair_create_assign_resolve_close",()->{try(Fixture f=new Fixture()){Map<String,Object> row=f.create("repair",repair(),STAFF);state(row,"open",1);row=f.act("repair","assign",row,Json.obj("assignee","301"),MANAGER);state(row,"assigned",2);row=f.act("repair","resolve",row,Json.obj("resolution","更换故障电源并复测"),TECH);state(row,"resolved",3);row=f.act("repair","close",row,Map.of(),STAFF);state(row,"closed",4);List<Object> events=arr(f.call("repair","history",Json.obj("id",row.get("id")),STAFF),"items");check(events.size()==4,"4 committed events");for(Object e:events)check(map(e).get("engine").equals("python"),"actual Python decisions");}});
        run("java_rejection_path",()->{try(Fixture f=new Fixture()){Map<String,Object> row=f.create("purchase",purchase(),STAFF);row=f.act("purchase","submit",row,Map.of(),STAFF);state(f.act("purchase","reject",row,Json.obj("comment","预算不足"),MANAGER),"rejected",3);}});
        run("wrong_role_denied",()->{try(Fixture f=new Fixture()){reject("FORBIDDEN",()->f.create("purchase",purchase(),TECH));check(f.store.list("tenant-a","purchase").isEmpty(),"no unauthorized record");}});
        run("cannot_approve_own_purchase",()->{try(Fixture f=new Fixture()){Map<String,Object> row=f.create("purchase",purchase(),MANAGER);row=f.act("purchase","submit",row,Map.of(),MANAGER);Map<String,Object> submitted=row;reject("BUSINESS_RULE",()->f.act("purchase","approve",submitted,Json.obj("comment","自审"),MANAGER));}});
        run("cannot_submit_another_requester_record",()->{try(Fixture f=new Fixture()){Map<String,Object> row=f.create("purchase",purchase(),STAFF);reject("BUSINESS_RULE",()->f.act("purchase","submit",row,Map.of(),MANAGER));}});
        run("cannot_read_another_requester_record",()->{try(Fixture f=new Fixture()){Map<String,Object> row=f.create("purchase",purchase(),STAFF);reject("FORBIDDEN",()->f.call("purchase","get",Json.obj("id",row.get("id")),OTHER));check(arr(f.call("purchase","list",Map.of(),OTHER),"items").isEmpty(),"list is scoped to actor");}});
        run("tenant_argument_cannot_inject_identity",()->{try(Fixture f=new Fixture()){Map<String,Object> request=Json.obj("data",purchase(),"requestKey",key(),"scope","tenant-b","subject","201");reject("INVALID_INPUT",()->f.call("purchase","create",request,STAFF));}});
        run("cross_tenant_record_unavailable",()->{try(Fixture f=new Fixture()){Map<String,Object> row=f.create("purchase",purchase(),STAFF);reject("NOT_FOUND",()->f.engine.invoke("tenant-b","purchase","get",Json.obj("id",row.get("id")),MANAGER,1L));}});
        run("same_request_same_result_no_duplicate_audit",()->{try(Fixture f=new Fixture()){Map<String,Object> req=Json.obj("data",purchase(),"requestKey",key());Map<String,Object> a=f.call("purchase","create",req,STAFF),b=f.call("purchase","create",req,STAFF);check(a.equals(b),"same result");check(f.store.list("tenant-a","purchase").size()==1,"one row");check(f.store.history("tenant-a","purchase",str(a.get("id"))).size()==1,"one event");}});
        run("same_key_changed_payload_is_conflict",()->{try(Fixture f=new Fixture()){String key=key();f.call("purchase","create",Json.obj("data",purchase(),"requestKey",key),STAFF);reject("IDEMPOTENCY_CONFLICT",()->f.call("purchase","create",Json.obj("data",Json.obj("title","另一个项目","amount","1.00"),"requestKey",key),STAFF));}});
        run("replay_does_not_bypass_revoked_permission",()->{try(Fixture f=new Fixture()){Map<String,Object> req=Json.obj("data",purchase(),"requestKey",key());f.call("purchase","create",req,STAFF);f.permitted.set(false);reject("FORBIDDEN",()->f.call("purchase","create",req,STAFF));}});
        run("stale_record_version_rejected",()->{try(Fixture f=new Fixture()){Map<String,Object> row=f.create("purchase",purchase(),STAFF);f.act("purchase","submit",row,Map.of(),STAFF);reject("RECORD_CONFLICT",()->f.act("purchase","submit",row,Map.of(),STAFF));}});
        run("cannot_skip_purchase_submission",()->{try(Fixture f=new Fixture()){Map<String,Object> row=f.create("purchase",purchase(),STAFF);reject("BUSINESS_RULE",()->f.act("purchase","approve",row,Json.obj("comment","跳过"),MANAGER));}});
        run("cannot_skip_repair_resolution",()->{try(Fixture f=new Fixture()){Map<String,Object> row=f.create("repair",repair(),STAFF);reject("BUSINESS_RULE",()->f.act("repair","close",row,Map.of(),STAFF));}});
        run("only_assigned_technician_may_resolve",()->{try(Fixture f=new Fixture()){Map<String,Object> row=f.create("repair",repair(),STAFF);Map<String,Object> assigned=f.act("repair","assign",row,Json.obj("assignee","301"),MANAGER);reject("BUSINESS_RULE",()->f.act("repair","resolve",assigned,Json.obj("resolution","越权处理"),MANAGER));}});
        run("money_uses_exact_decimal_string",()->{try(Fixture f=new Fixture()){Map<String,Object> large=f.create("purchase",Json.obj("title","精度测试","amount","9999999999.99"),STAFF);check(obj(large,"body").get("amount").equals("9999999999.99"),"decimal preserved");reject("INVALID_INPUT",()->f.create("purchase",Json.obj("title","数值输入","amount",1.23),STAFF));reject("BUSINESS_RULE",()->f.create("purchase",Json.obj("title","多余精度","amount","1.234"),STAFF));}});
        run("unknown_fields_rejected_by_contract",()->{try(Fixture f=new Fixture()){reject("INVALID_INPUT",()->f.create("repair",Json.obj("title","x","description","x","severity","normal","status","closed"),STAFF));}});
        run("business_error_leaves_python_available",()->{try(Fixture f=new Fixture()){Map<String,Object> row=f.create("repair",repair(),STAFF);reject("BUSINESS_RULE",()->f.act("repair","close",row,Map.of(),STAFF));state(f.act("repair","assign",row,Json.obj("assignee","301"),MANAGER),"assigned",2);}});
        run("parallel_identical_creates_commit_once",()->{try(Fixture f=new Fixture()){Map<String,Object> req=Json.obj("data",purchase(),"requestKey",key());ExecutorService pool=Executors.newFixedThreadPool(8);try{List<Future<Map<String,Object>>> tasks=new ArrayList<>();for(int n=0;n<16;n++)tasks.add(pool.submit(()->f.call("purchase","create",req,STAFF)));Map<String,Object> first=tasks.get(0).get(3,TimeUnit.SECONDS);for(Future<Map<String,Object>> t:tasks)check(t.get(3,TimeUnit.SECONDS).equals(first),"one idempotent response");check(f.store.list("tenant-a","purchase").size()==1,"one row after concurrency");}finally{pool.shutdownNow();}}});
        run("two_modules_have_independent_data",()->{try(Fixture f=new Fixture()){f.create("purchase",purchase(),STAFF);f.create("repair",repair(),STAFF);check(f.store.list("tenant-a","purchase").size()==1,"one purchase");check(f.store.list("tenant-a","repair").size()==1,"one repair");}});
        run("disabling_python_preserves_java_and_history",()->{try(Fixture f=new Fixture()){Map<String,Object> purchase=f.create("purchase",purchase(),STAFF);Map<String,Object> repair=f.create("repair",repair(),STAFF);f.engine.publish("tenant-a","ruoyi.java-only",1);f.generation=2;reject("CAPABILITY_MISSING",()->f.call("repair","list",Map.of(),STAFF));state(f.act("purchase","submit",purchase,Map.of(),STAFF),"submitted",2);check(f.store.get("tenant-a","repair",str(repair.get("id")))!=null,"disabled plugin data retained");f.engine.publish("tenant-a","ruoyi.dual",2);f.generation=3;state(f.call("repair","get",Json.obj("id",repair.get("id")),STAFF),"open",1);}});
        run("restart_preserves_data_and_idempotency",()->{Path file=Files.createTempDirectory("fcp-restart-").resolve("records.json");Map<String,Object> req=Json.obj("data",repair(),"requestKey",key()),saved;String oldInstance;try(Fixture f=new Fixture(root,file)){saved=f.call("repair","create",req,STAFF);oldInstance=f.instance;}try(Fixture f=new Fixture(root,file)){check(saved.equals(f.call("repair","create",req,STAFF)),"persisted replay");check(f.store.list("tenant-a","repair").size()==1,"no duplicate after restart");reject("STALE_COMPOSITION",()->f.engine.invoke("tenant-a","repair","list",Map.of(),STAFF,1L,oldInstance));}});
        run("python_timeout_does_not_block_native_java_and_recovers",()->{
            Path runtime=copyRuntime();Path delay=runtime.resolve("delay.flag"),entered=runtime.resolve("worker.entered");
            String wrapper="import os, pathlib, sys, time\nsys.path.insert(0,str(pathlib.Path(__file__).parent))\nimport repair\noriginal=repair.plan\ndef slow(p):\n pathlib.Path('worker.entered').write_text(str(os.getpid()))\n if pathlib.Path('delay.flag').exists(): time.sleep(10)\n return original(p)\nrepair.plan=slow\nrepair.run()\n";
            Files.writeString(runtime.resolve("plugins/slow_fixture.py"),wrapper);Map<String,Object> launch=map(Json.parse(Files.readString(runtime.resolve("apps/launchers.json"))));arr(obj(launch,"repair.python"),"argv").set(1,"{root}/plugins/slow_fixture.py");Files.writeString(runtime.resolve("apps/launchers.json"),Json.write(launch));Files.writeString(delay,"test fixture only");
            ExecutorService pool=Executors.newFixedThreadPool(2);
            try(Fixture f=new Fixture(runtime,Files.createTempDirectory("fcp-timeout-").resolve("records.json"))){Future<?> slow=pool.submit(()->reject("DEADLINE",()->f.create("repair",repair(),STAFF)));long until=System.nanoTime()+TimeUnit.SECONDS.toNanos(2);while(!Files.exists(entered)&&System.nanoTime()<until)Thread.sleep(5);check(Files.exists(entered),"actual Python process entered");String pid=Files.readString(entered);Map<String,Object> java=pool.submit(()->f.create("purchase",purchase(),STAFF)).get(1200,TimeUnit.MILLISECONDS);state(java,"draft",1);check(!slow.isDone(),"Java completed while Python still waiting");slow.get(4,TimeUnit.SECONDS);check(f.store.list("tenant-a","repair").isEmpty(),"timeout produced no write");Files.delete(delay);state(f.create("repair",repair(),STAFF),"open",1);check(!pid.equals(Files.readString(entered)),"replacement Python process started");}finally{pool.shutdownNow();}
        });
        run("malformed_python_frame_is_retired_then_recovers",()->{
            Path runtime=copyRuntime();Path flag=runtime.resolve("malformed.flag");
            String wrapper="import pathlib, sys\nsys.path.insert(0,str(pathlib.Path(__file__).parent))\nimport repair\nif pathlib.Path('malformed.flag').exists():\n for line in sys.stdin: print('{', flush=True)\nelse: repair.run()\n";
            Files.writeString(runtime.resolve("plugins/malformed_fixture.py"),wrapper);Map<String,Object> launch=map(Json.parse(Files.readString(runtime.resolve("apps/launchers.json"))));arr(obj(launch,"repair.python"),"argv").set(1,"{root}/plugins/malformed_fixture.py");Files.writeString(runtime.resolve("apps/launchers.json"),Json.write(launch));Files.writeString(flag,"controlled regression fixture");
            try(Fixture f=new Fixture(runtime,Files.createTempDirectory("fcp-malformed-").resolve("records.json"))){reject("TRANSPORT",()->f.create("repair",repair(),STAFF));check(f.store.list("tenant-a","repair").isEmpty(),"no write on malformed response");Files.delete(flag);state(f.create("repair",repair(),STAFF),"open",1);}
        });
        long failed=tests.stream().filter(t->map(t).get("status").equals("FAIL")).count();System.out.println(Json.write(Json.obj("suite","dual-flow-jvm-python","scope","actual JVM and Python, file-backed test store; NOT RuoYi/JDBC E2E","passed",tests.size()-failed,"failed",failed,"tests",tests)));if(failed>0)System.exit(1);
    }
}
